//  Avatar — Editorial
// ============================================================
function Avatar({ user, size = 'lg' }) {
  const initial = (user.full_name || user.username || '?')
    .trim()
    .charAt(0)
    .toUpperCase();
  const gradient = getAvatarGradient(user.id);
  const sizeCls =
    size === 'sm'
      ? 'w-8 h-8 text-xs'
      : size === 'xl'
      ? 'w-16 h-16 sm:w-20 sm:h-20 text-2xl sm:text-3xl'
      : size === 'lg'
      ? 'w-12 h-12 text-lg'
      : 'w-10 h-10 text-sm';

  return (
    <div
      className={`${sizeCls} bg-gradient-to-br ${gradient} rounded-full flex items-center justify-center text-white font-black flex-shrink-0 shadow-editorial ring-4 ring-paper-50 dark:ring-ink-800`}
    >
      {initial}
    </div>
  );
}

// ============================================================
//  StatCard — Editorial
// ============================================================
function StatCard({
  icon,
  value,
  label,
  gradient = 'from-ink-500 to-ink-700',
  onClick,
}) {
  return (
    <div
      onClick={onClick}
      role={onClick ? 'button' : undefined}
      tabIndex={onClick ? 0 : undefined}
      onKeyDown={
        onClick
          ? (e) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onClick();
              }
            }
          : undefined
      }
      className={`bg-gradient-to-br ${gradient} text-white rounded-3xl p-3 text-center shadow-soft transition-all ${
        onClick
          ? 'cursor-pointer hover:shadow-lifted hover:-translate-y-0.5 active:scale-[0.97] touch-target focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-white/50'
          : ''
      } relative overflow-hidden`}
    >
      <div
        className="absolute -top-4 -right-4 w-12 h-12 bg-white/10 rounded-full"
        aria-hidden="true"
      />
      <div className="relative">
        <div className="text-lg sm:text-xl mb-1" aria-hidden="true">
          {icon}
        </div>
        {/* ✅ FIX: font-num */}
        <div className="text-sm sm:text-base font-display font-black truncate tracking-tight font-num tabular-nums">
          {value}
        </div>
        <div className="text-[10px] opacity-90 mt-0.5 truncate font-black">
          {label}
        </div>
      </div>
    </div>
  );
}

// ============================================================
//  Contact Row — Editorial
// ============================================================
function ContactRow({ icon, label, value, onCopy, mono = false, dir = 'rtl', badge }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    if (!value || value === '—') return;
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      onCopy?.();
      setTimeout(() => setCopied(false), 1500);
    } catch {
      /* silent */
    }
  };

  return (
    <div className="flex items-center gap-3 py-3 min-h-[56px] border-b border-ink-200 dark:border-dark-700 last:border-b-0">
      <div
        className="w-10 h-10 rounded-2xl bg-paper-100 dark:bg-ink-700 flex items-center justify-center flex-shrink-0 text-base"
        aria-hidden="true"
      >
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-[10px] text-ink-400 dark:text-cream-500 mb-0.5 font-bold">
          {label}
        </div>
        <div
          className={`text-xs font-black text-ink-800 dark:text-cream-100 break-safe ${
            mono ? 'font-mono tabular-nums' : ''
          }`}
          dir={dir}
        >
          {value || (
            <span className="text-ink-300 dark:text-dark-600 font-normal">
              —
            </span>
          )}
        </div>
      </div>
      {badge}
      {value && value !== '—' && (
        <button
          type="button"
          onClick={handleCopy}
          className={`w-10 h-10 flex items-center justify-center rounded-2xl transition text-sm flex-shrink-0 touch-target ${
            copied
              ? 'bg-accent-100 dark:bg-accent-500/20 text-accent-600 dark:text-accent-400'
              : 'bg-paper-100 dark:bg-ink-700 hover:bg-paper-200 dark:hover:bg-ink-600 text-ink-500 dark:text-cream-400'
          }`}
          title="کپی"
          aria-label="کپی"
        >
          {copied ? '✓' : '📋'}
        </button>
      )}
    </div>
  );
}

