// ============================================================
//  LogoUploader
//  ✅ FIX: SVG حذف شد (backend پشتیبانی نمی‌کند)
//  ✅ FIX: مسیرهای API نسبی
// ============================================================
function LogoUploader({ currentUrl, onUploaded, onDeleted }) {
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState(currentUrl || '');
  const [error, setError] = useState('');
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef(null);

  useEffect(() => {
    setPreview(currentUrl || '');
  }, [currentUrl]);

  const handleFileSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setError('');
    setUploading(true);

    // ✅ FIX: SVG حذف شد
    const allowedExts = ['.png', '.jpg', '.jpeg', '.webp', '.gif'];
    const ext = '.' + file.name.split('.').pop().toLowerCase();
    if (!allowedExts.includes(ext)) {
      setError(`پسوند ${ext} مجاز نیست. فقط PNG, JPG, WEBP, GIF پذیرفته می‌شود.`);
      setUploading(false);
      return;
    }
    if (file.size > 2 * 1024 * 1024) {
      setError('حجم فایل بیش از ۲ مگابایت است.');
      setUploading(false);
      return;
    }

    try {
      const formData = new FormData();
      formData.append('file', file);

      // ✅ FIX: مسیر نسبی
      const res = await axios.post('/admin/upload-logo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });

      if (res.data.success) {
        const newUrl = res.data.url;
        setPreview(newUrl);
        onUploaded(newUrl);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    } catch (err) {
      setError(getErrorMsg(err, 'خطا در آپلود لوگو'));
    } finally {
      setUploading(false);
    }
  };

  const handleRemove = async () => {
    if (!window.confirm('لوگوی فعلی حذف شود؟')) return;

    setUploading(true);
    try {
      if (preview && preview.startsWith('/uploads/')) {
        // ✅ FIX: مسیر نسبی
        await axios.delete('/admin/upload-logo');
      }
      setPreview('');
      onDeleted();
    } catch {
      setError('خطا در حذف لوگو');
    } finally {
      setUploading(false);
    }
  };

  const fullPreviewUrl = preview
    ? preview.startsWith('http')
      ? preview
      : `${API_BASE}${preview}`
    : '';

  return (
    <div className="space-y-3">
      <div
        onClick={() => !uploading && fileInputRef.current?.click()}
        onDragOver={(e) => {
          e.preventDefault();
          setDragOver(true);
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={(e) => {
          e.preventDefault();
          setDragOver(false);
          if (uploading) return;
          const file = e.dataTransfer.files?.[0];
          if (file && fileInputRef.current) {
            const dt = new DataTransfer();
            dt.items.add(file);
            fileInputRef.current.files = dt.files;
            handleFileSelect({ target: fileInputRef.current });
          }
        }}
        className={`relative border-2 border-dashed rounded-2xl p-4 sm:p-6 min-h-[140px] sm:min-h-[160px] text-center cursor-pointer transition flex items-center justify-center touch-target ${
          uploading
            ? 'border-accent-300 dark:border-accent-500/40 bg-accent-50 dark:bg-accent-500/15 cursor-wait'
            : error
            ? 'border-rose-300 dark:border-rose-500/40 bg-rose-50 dark:bg-rose-500/15'
            : dragOver
            ? 'border-brand-500 bg-brand-50 dark:bg-brand-500/15 scale-[1.02]'
            : 'border-ink-200 dark:border-dark-600 bg-paper-100 dark:bg-ink-700/40 hover:border-brand-400 dark:hover:border-brand-500/50 hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 dark:active:bg-brand-500/25'
        }`}
      >
        <input
          ref={fileInputRef}
          type="file"
          accept=".png,.jpg,.jpeg,.webp,.gif"
          onChange={handleFileSelect}
          className="hidden"
          disabled={uploading}
        />

        {uploading ? (
          <div className="flex flex-col items-center gap-3">
            <div className="w-10 h-10 border-4 border-brand-500 border-t-transparent rounded-full animate-spin" />
            <div className="text-sm text-brand-700 dark:text-brand-300 font-black">
              در حال آپلود...
            </div>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-1.5">
            <div className="text-3xl sm:text-4xl mb-1" aria-hidden="true">🖼️</div>
            <div className="text-xs sm:text-sm font-black text-ink-700 dark:text-cream-200 text-center leading-relaxed px-2">
              کلیک کنید یا فایل را اینجا بکشید
            </div>
            <div className="text-[10px] text-ink-400 dark:text-cream-500 text-center leading-relaxed px-2 font-bold">
              PNG, JPG, WEBP, GIF — حداکثر ۲ مگابایت
            </div>
          </div>
        )}
      </div>

      {error && (
        <div className="bg-rose-50 dark:bg-rose-500/15 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 p-3 rounded-2xl text-xs flex items-start gap-2 animate-slide-down break-safe font-bold">
          <span className="flex-shrink-0" aria-hidden="true">⚠️</span>
          <span>{error}</span>
        </div>
      )}

      {preview && (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl p-3 sm:p-4 shadow-soft">
          <div className="flex items-center justify-between gap-2 mb-2.5 flex-wrap">
            <div className="text-[11px] sm:text-xs font-black text-ink-600 dark:text-cream-300 flex items-center gap-1.5">
              <SiteImage imageKey="icon_check" fallback="✅" alt="" className="leading-none inline-flex" />
              <span>لوگوی فعلی:</span>
            </div>
            <div className="flex gap-1 flex-shrink-0">
              <button
                type="button"
                onClick={() => fileInputRef.current?.click()}
                disabled={uploading}
                className="min-h-[36px] px-2.5 py-1.5 text-xs text-brand-600 dark:text-brand-400 hover:text-brand-800 dark:hover:text-brand-300 font-black rounded-xl hover:bg-brand-50 dark:hover:bg-brand-500/15 active:bg-brand-100 dark:active:bg-brand-500/25 transition flex items-center gap-1 touch-target"
              >
                <SiteImage imageKey="icon_refresh" fallback="🔄" alt="" className="leading-none inline-flex" />
                <span>تغییر</span>
              </button>
              <button
                type="button"
                onClick={handleRemove}
                disabled={uploading}
                className="min-h-[36px] px-2.5 py-1.5 text-xs text-rose-600 dark:text-rose-400 hover:text-rose-800 dark:hover:text-rose-300 font-black rounded-xl hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 dark:active:bg-rose-500/25 transition flex items-center gap-1 touch-target"
              >
                <span aria-hidden="true">🗑️</span>
                <span>حذف</span>
              </button>
            </div>
          </div>
          <div className="bg-paper-100 dark:bg-ink-900/50 rounded-2xl p-3 sm:p-4 flex items-center justify-center min-h-[100px] border border-ink-200 dark:border-dark-600">
            <img
              src={fullPreviewUrl}
              alt="لوگو"
              className="max-h-20 object-contain hover:scale-105 transition-transform"
              onError={(e) => {
                e.target.style.display = 'none';
                if (e.target.nextSibling) e.target.nextSibling.style.display = 'block';
              }}
            />
            <div className="hidden text-xs text-rose-600 dark:text-rose-400 font-bold">
              ❌ تصویر بارگذاری نشد
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================
//  PriceCalculator
// ============================================================
function PriceCalculator({ settings }) {
  const sampleMaterial = 100000;

  const labor = sampleMaterial * (parseFloat(normalizeDigits(settings.overhead_labor_percent)) / 100);
  const fuel = sampleMaterial * (parseFloat(normalizeDigits(settings.overhead_fuel_percent)) / 100);
  const waste = sampleMaterial * (parseFloat(normalizeDigits(settings.overhead_waste_percent)) / 100);
  const packaging = parseFloat(normalizeDigits(settings.overhead_packaging_fixed));
  const overhead = labor + fuel + waste + packaging;
  const totalCost = sampleMaterial + overhead;
  const profit = totalCost * (parseFloat(normalizeDigits(settings.profit_percent)) / 100);
  const finalPrice = totalCost + profit;

  const fmt = (n) => Math.round(n).toLocaleString('fa-IR');

  const rows = [
    { label: 'مواد اولیه (فرضی)', value: sampleMaterial, color: 'text-brand-700 dark:text-brand-400', icon: '🥩', iconKey: 'allergen_beef', type: 'base' },
    { label: `نیروی کار (${toFa(settings.overhead_labor_percent)}٪)`, value: labor, color: 'text-ink-700 dark:text-cream-200', icon: '👷', type: 'normal' },
    { label: `سوخت (${toFa(settings.overhead_fuel_percent)}٪)`, value: fuel, color: 'text-ink-700 dark:text-cream-200', icon: '⛽', type: 'normal' },
    { label: `ضایعات (${toFa(settings.overhead_waste_percent)}٪)`, value: waste, color: 'text-ink-700 dark:text-cream-200', icon: '♻️', type: 'normal' },
    // ✅ FIX: برچسب به بسته‌بندی (روزانه) تغییر کرد
    { label: 'بسته‌بندی (روزانه)', value: packaging, color: 'text-ink-700 dark:text-cream-200', icon: '📦', iconKey: 'icon_orders', type: 'normal' },
    { label: 'جمع سربار', value: overhead, color: 'text-brand-700 dark:text-brand-400', icon: '📊', iconKey: 'icon_chart', type: 'overhead' },
    { label: 'هزینه تمام‌شده', value: totalCost, color: 'text-ink-800 dark:text-cream-100', icon: '💰', iconKey: 'icon_money', type: 'cost' },
    { label: `سود (${toFa(settings.profit_percent)}٪)`, value: profit, color: 'text-brand-700 dark:text-brand-400', icon: '💎', iconKey: 'icon_gem', type: 'profit' },
    { label: 'قیمت نهایی روزانه', value: finalPrice, color: 'text-accent-700 dark:text-accent-400', icon: '🎯', iconKey: 'icon_target', type: 'final' },
  ];

  return (
    <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
      <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-paper-100/50 dark:bg-ink-900/30">
        <div className="w-10 h-10 rounded-2xl bg-brand-gradient flex items-center justify-center text-xl shadow-brand flex-shrink-0" aria-hidden="true">
          🧮
        </div>
        <div className="flex-1 min-w-0">
          <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
            پیش‌نمایش محاسبه
          </div>
          <div className="text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 font-bold">
            با فرض ۱۰۰٬۰۰۰ تومان مواد اولیه
          </div>
        </div>
      </div>

      <div className="p-3 sm:p-4 space-y-1.5">
        {rows.map((row, i) => {
          const isBold = ['overhead', 'cost', 'profit', 'final'].includes(row.type);
          const isFinal = row.type === 'final';

          return (
            <div
              key={i}
              className={`flex justify-between items-center gap-2 py-2 px-2.5 sm:px-3 rounded-2xl transition ${
                isFinal
                  ? 'bg-brand-gradient text-white shadow-brand'
                  : isBold
                  ? 'bg-paper-100 dark:bg-ink-700/50 border border-ink-200 dark:border-dark-600'
                  : ''
              }`}
            >
              <span
                className={`text-[11px] sm:text-xs flex items-center gap-1.5 min-w-0 ${
                  isFinal
                    ? 'font-black text-white'
                    : isBold
                    ? 'font-black text-ink-800 dark:text-cream-100'
                    : 'text-ink-600 dark:text-cream-300 font-bold'
                }`}
              >
                <span className="flex-shrink-0" aria-hidden="true">{row.icon}</span>
                <span className="truncate">{row.label}</span>
              </span>
              <span
                className={`text-[11px] sm:text-xs font-num flex-shrink-0 tabular-nums ${
                  isFinal
                    ? 'text-white text-base font-black'
                    : row.color + ' ' + (isBold ? 'font-black' : 'font-bold')
                }`}
              >
                {fmt(row.value)}
                <span
                  className={`text-[10px] mr-1 ${
                    isFinal ? 'opacity-80' : 'text-ink-400 dark:text-cream-500'
                  }`}
                >
                  ت
                </span>
              </span>
            </div>
          );
        })}
      </div>

      <div className="px-3 sm:px-4 pb-3 sm:pb-4">
        <div className="bg-brand-50 dark:bg-brand-500/15 border border-brand-200 dark:border-brand-500/30 rounded-2xl p-2.5 text-[10px] leading-relaxed text-brand-800 dark:text-brand-200 font-bold flex items-start gap-1.5">
          <span className="flex-shrink-0 mt-0.5" aria-hidden="true">ℹ️</span>
          <span className="break-safe">
            این عدد <strong>شامل هزینه ارسال نیست</strong> — هزینه ارسال طبق تنظیمات تب «ارسال» جداگانه اعمال می‌شود.
          </span>
        </div>
      </div>
    </div>
  );
}

