// ============================================================
//  Sort Icon
// ============================================================
function SortIcon({ columnKey, sortConfig }) {
  if (sortConfig.key !== columnKey) {
    return (
      <SiteImage imageKey="icon_sort" fallback="↕" alt="" className="text-cream-100/40 text-[10px]" />
    );
  }
  return sortConfig.direction === 'asc' ? (
    <SiteImage imageKey="icon_sort_up" fallback="▲" alt="" className="text-cream-50 text-[10px]" />
  ) : (
    <SiteImage imageKey="icon_sort_down" fallback="▼" alt="" className="text-cream-50 text-[10px]" />
  );
}

// ============================================================
//  FormField
// ============================================================
function FormField({ label, hint, children, required, unit, icon }) {
  return (
    <div>
      <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
        {icon && (
          <span className="text-sm flex-shrink-0" aria-hidden="true">
            {icon}
          </span>
        )}
        <span>{label}</span>
        {required && <span className="text-brand-500">*</span>}
        {unit && (
          <span className="text-ink-400 dark:text-cream-500 font-normal">
            ({unit})
          </span>
        )}
      </label>
      {children}
      {hint && (
        <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed font-bold">
          {hint}
        </div>
      )}
    </div>
  );
}

