function ActionButton({
  onClick,
  variant = 'default',
  icon,
  label,
  title,
  disabled = false,
  fullWidthOnMobile = false,
}) {
  const variants = {
    primary:
      'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand',
    blue:
      'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand',
    purple:
      'bg-accent-500 hover:bg-accent-600 active:bg-accent-700 text-white shadow-soft',
    indigo:
      'bg-ink-800 hover:bg-ink-700 active:bg-ink-600 text-cream-100 shadow-soft',
    success:
      'bg-accent-600 hover:bg-accent-700 active:bg-accent-800 text-white shadow-soft',
    danger:
      'bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 text-rose-700 dark:text-rose-300 border border-rose-200 dark:border-rose-500/30',
    ghost:
      'bg-paper-100 dark:bg-ink-700 hover:bg-paper-200 dark:hover:bg-ink-600 text-ink-700 dark:text-cream-200 border border-ink-200 dark:border-dark-600',
  };
  return (
    <button
      type="button"
      onClick={onClick}
      title={title}
      disabled={disabled}
      className={`
        px-3 sm:px-4 py-2.5 rounded-2xl text-sm font-black
        transition flex items-center justify-center gap-1.5
        disabled:opacity-50 disabled:cursor-not-allowed
        hover:-translate-y-0.5 active:translate-y-0
        min-h-[44px] touch-target
        ${fullWidthOnMobile ? 'flex-1 sm:flex-none' : ''}
        ${variants[variant]}
      `}
    >
      {icon && (
        <span className="text-base" aria-hidden="true">
          {icon}
        </span>
      )}
      {label && <span>{label}</span>}
    </button>
  );
}

// ============================================================
//  Red Dot — Editorial
// ============================================================
function RedDot({ pulse = true }) {
  return (
    <span
      className={`w-2.5 h-2.5 rounded-full bg-rose-500 shadow-soft ${
        pulse ? 'animate-pulse' : ''
      }`}
      style={{ boxShadow: '0 0 0 2px rgba(244, 63, 94, 0.3)' }}
      aria-hidden="true"
    />
  );
}

// ============================================================
//  Menu Badge — Editorial
// ============================================================
function MenuBadge({ count, color = 'rose' }) {
  if (!count || count <= 0) return null;
  const colors = {
    rose: 'bg-rose-500 text-white',
    brand: 'bg-brand-500 text-white',
    accent: 'bg-accent-500 text-white',
    ink: 'bg-ink-800 text-cream-100',
  };
  return (
    <span
      className={`${
        colors[color] || colors.rose
      } text-[10px] font-black min-w-[18px] h-[18px] px-1 rounded-full flex items-center justify-center shadow-soft font-num tabular-nums`}
    >
      {count > 99 ? '۹۹+' : toFa(count)}
    </span>
  );
}

