    localStorage.removeItem('adminNotificationsLastSeen');

    lastSeenTicketTotalRef.current = null;
    lastSeenPaymentsRef.current = null;
    isFirstPollRef.current = true;
    hasNotifiedTicketRef.current = false;
    hasNotifiedPaymentRef.current = false;
    ticketNotifyCooldownRef.current = 0;
    paymentNotifyCooldownRef.current = 0;

    setShowUserMenu(false);
    window.location.href = '/admin/login';
