// ============================================================
//  🛡️ Helpers
// ============================================================
const getErrorMsg = (err, fallback) => {
  const detail = err?.response?.data?.detail;
  if (typeof detail === 'string') return detail;
  return fallback;
};

const isBatchPayment = (p) =>
  Boolean(p?.batch_id) && Number(p?.batch_size || 1) > 1;

// ============================================================
//  ✅ NEW: useReceiptBlobUrl — دریافت امن فیش
//  - برای /admin/receipts/... → axios blob (با توکن)
//  - برای /uploads/receipts/... (legacy) → URL مستقیم
// ============================================================
function useReceiptBlobUrl(receiptUrl) {
  const [blobUrl, setBlobUrl] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const urlRef = useRef('');

  useEffect(() => {
    // پاک‌سازی قبلی
    if (urlRef.current && urlRef.current.startsWith('blob:')) {
      URL.revokeObjectURL(urlRef.current);
    }
    urlRef.current = '';
    setBlobUrl('');
    setError('');

    if (!receiptUrl) {
      setLoading(false);
      return;
    }

    // Legacy public URL → مستقیم
    if (receiptUrl.startsWith('/uploads/receipts/')) {
      const full = resolveAssetUrl(receiptUrl);
      urlRef.current = full;
      setBlobUrl(full);
      setLoading(false);
      return;
    }

    // Auth-required → blob
    setLoading(true);
    let cancelled = false;

    axios
      .get(receiptUrl, { responseType: 'blob' })
      .then((res) => {
        if (cancelled) return;
        const obj = URL.createObjectURL(res.data);
        urlRef.current = obj;
        setBlobUrl(obj);
      })
      .catch((err) => {
        if (cancelled) return;
        setError(getErrorMsg(err, 'خطا در بارگذاری فیش'));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [receiptUrl]);

  // Cleanup در unmount
  useEffect(() => {
    return () => {
      if (urlRef.current && urlRef.current.startsWith('blob:')) {
        URL.revokeObjectURL(urlRef.current);
      }
    };
  }, []);

  return { blobUrl, loading, error };
}

