// ============================================================
//  Avatar
// ============================================================
function Avatar({ name, id, size = 'md' }) {
  const initial = (name || '?').trim().charAt(0).toUpperCase();
  const gradient = getAvatarGradient(id);
  const sizeCls =
    size === 'sm'
      ? 'w-8 h-8 text-xs'
      : size === 'lg'
      ? 'w-12 h-12 text-lg'
      : size === 'xl'
      ? 'w-16 h-16 text-2xl'
      : 'w-10 h-10 text-sm';

  return (
    <div
      className={`${sizeCls} bg-gradient-to-br ${gradient} rounded-full flex items-center justify-center text-white font-black flex-shrink-0 shadow-soft ring-2 ring-paper-50 dark:ring-ink-800`}
    >
      {initial}
    </div>
  );
}

