  new_receipt: { icon: '💳', iconKey: 'icon_payment', label: 'فیش جدید', color: 'accent' },
  cancelled_order: { icon: '❌', iconKey: 'icon_error', label: 'لغو سفارش', color: 'rose' },
  new_ticket: { icon: '🎫', iconKey: 'icon_ticket', label: 'تیکت جدید', color: 'brand' },
  user_reply: { icon: '💬', iconKey: 'icon_chat', label: 'پاسخ کاربر', color: 'ink' },
  new_testimonial: { icon: '⭐', iconKey: 'icon_star', label: 'نظر جدید', color: 'accent' },
