const FILTER_CHIPS = [
  { key: 'all', label: 'همه', icon: '📋', iconKey: 'icon_clipboard' },
  { key: 'new_order', label: 'سفارش', icon: '🆕', iconKey: 'icon_new' },
  { key: 'new_receipt', label: 'فیش', icon: '💳', iconKey: 'icon_payment' },
  { key: 'cancelled_order', label: 'لغو', icon: '❌', iconKey: 'icon_error' },
  { key: 'new_ticket', label: 'تیکت', icon: '🎫', iconKey: 'icon_ticket' },
  { key: 'user_reply', label: 'پاسخ کاربر', icon: '💬', iconKey: 'icon_chat' },
  { key: 'new_testimonial', label: 'نظر', icon: '⭐', iconKey: 'icon_star' },
];

function safeDate(iso) {
  if (!iso) return null;
  let s = String(iso);
  if (!s.includes('Z') && !/[+-]\d{2}:?\d{2}$/.test(s)) s = s + 'Z';
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function toFaTimeAgo(iso) {
  const d = safeDate(iso);
  if (!d) return '—';
  const diff = Date.now() - d.getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return 'همین الان';
  if (mins < 60) return `${toFaRaw(mins)} دقیقه پیش`;
  const hours = Math.floor(mins / 60);
  if (hours < 24) return `${toFaRaw(hours)} ساعت پیش`;
  const days = Math.floor(hours / 24);
  if (days < 7) return `${toFaRaw(days)} روز پیش`;
  return new Intl.DateTimeFormat('fa-IR', {
    month: 'short',
    day: 'numeric',
  }).format(d);
}

function readLastSeen() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const d = new Date(raw);
    return isNaN(d.getTime()) ? null : d;
  } catch {
    return null;
  }
}

function writeLastSeen(date) {
  try {
    localStorage.setItem(STORAGE_KEY, date.toISOString());
  } catch {
    /* silent */
  }
}

// ✅ FIX: initial state — هماهنگ با AdminNotificationCenter
function getInitialLastSeen() {
  const stored = readLastSeen();
  if (stored) return stored;
  const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
  writeLastSeen(oneHourAgo);
  return oneHourAgo;
}

function isSameDay(a, b) {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function dayLabel(date) {
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);

  if (isSameDay(date, today)) return 'امروز';
  if (isSameDay(date, yesterday)) return 'دیروز';
  return new Intl.DateTimeFormat('fa-IR', {
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  }).format(date);
}

// ============================================================
//  ✅ NEW: normalizeLink
//  لینک‌های backend اکنون ?section=... هستند، اما برای سازگاری
//  با لینک‌های قدیمی، pathname را به query تبدیل می‌کند.
// ============================================================
function normalizeLink(link) {
  if (!link) return '';
  if (link.includes('section=')) return link;
  if (link === '/admin/notifications') return '/admin?section=notifications';
  if (link === '/admin/payments') return '/admin?section=payments';
  if (link === '/admin/tickets') return '/admin?section=tickets';
  if (link === '/admin/users') return '/admin?section=users';
  if (link === '/admin/orders') return '/admin?section=orders';
  if (link === '/admin') return '/admin?section=dashboard';
  const orderMatch = link.match(/^\/admin\/orders\/(\d+)$/);
  if (orderMatch) {
    return `/admin?section=order-detail&orderId=${orderMatch[1]}`;
  }
  return link;
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function NotificationsList() {
  const navigate = useNavigate();

  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);
  const [activeFilter, setActiveFilter] = useState('all');
  const [searchInput, setSearchInput] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [lastSeen, setLastSeen] = useState(getInitialLastSeen);
  const [refreshing, setRefreshing] = useState(false);

  // ✅ FIX: isMobile state — breakpoint هماهنگ با Dashboard/OrdersList
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.innerWidth < MOBILE_BREAKPOINT : false
  );

  const isMountedRef = useRef(true);

  // ============================================================
  //  Cleanup
  // ============================================================
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  // ✅ FIX: useEffect برای tracking resize
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  // ============================================================
  //  Fetch
  // ============================================================
  const fetchFeed = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    else setRefreshing(true);
    try {
      const res = await axios.get('/admin/notifications/feed', {
        params: { limit: FEED_LIMIT },
      });
      if (!isMountedRef.current) return;
      setEvents(res.data?.events || []);
    } catch {
      if (!isMountedRef.current) return;
      // silent — همان رفتار قبلی
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
        setRefreshing(false);
      }
    }
  }, []);

  useEffect(() => {
    fetchFeed();
    const id = setInterval(() => {
      if (document.visibilityState === 'visible') fetchFeed(true);
    }, 60000);
    return () => clearInterval(id);
  }, [fetchFeed]);

  // Debounce search
  useEffect(() => {
    const t = setTimeout(() => setSearchTerm(searchInput), 300);
    return () => clearTimeout(t);
  }, [searchInput]);

  // ============================================================
  //  Derived
  // ============================================================
  const isUnread = useCallback(
    (ev) => {
      if (!lastSeen) return true;
      const d = safeDate(ev.created_at);
      return d ? d > lastSeen : false;
    },
    [lastSeen]
  );

  const filtered = useMemo(() => {
    let list = events;
    if (activeFilter !== 'all') {
      list = list.filter((e) => e.type === activeFilter);
    }
    if (searchTerm.trim()) {
      const q = searchTerm.trim().toLowerCase();
      list = list.filter(
        (e) =>
          (e.title || '').toLowerCase().includes(q) ||
          (e.message || '').toLowerCase().includes(q)
      );
    }
    return list;
  }, [events, activeFilter, searchTerm]);

  const groupedByDay = useMemo(() => {
    const groups = new Map();
    for (const ev of filtered) {
      const d = safeDate(ev.created_at);
      if (!d) continue;
      const key = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
      if (!groups.has(key)) {
        groups.set(key, { date: d, events: [] });
      }
      groups.get(key).events.push(ev);
    }
    return Array.from(groups.values()).sort((a, b) => b.date - a.date);
  }, [filtered]);

  const unreadCount = useMemo(
    () => events.filter(isUnread).length,
    [events, isUnread]
  );

  const handleMarkAllSeen = () => {
    const now = new Date();
    writeLastSeen(now);
    setLastSeen(now);
  };

  // ✅ FIX: استفاده از normalizeLink برای سازگاری با لینک‌های قدیمی
  const handleClick = (event) => {
    const target = normalizeLink(event.link);
    if (target) navigate(target);
  };

  // ✅ FIX: hasActiveFilters به boolean
  const hasActiveFilters = Boolean(
    activeFilter !== 'all' || searchTerm.trim()
  );

  const clearFilters = () => {
    setActiveFilter('all');
    setSearchInput('');
    setSearchTerm('');
  };

  // ✅ FIX: کلاس container بر اساس isMobile
  const containerClass = isMobile
    ? 'p-3 sm:p-4 w-full space-y-4'
    : 'p-3 sm:p-4 max-w-5xl mx-auto space-y-4';

  return (
    <div className={containerClass} dir="rtl">
      {/* Hero Header */}
      <div className="bg-ink-900 dark:bg-ink-950 text-cream-100 rounded-3xl shadow-editorial relative overflow-hidden noise-overlay">
        <div
          className="absolute -top-16 -left-16 w-48 h-48 bg-brand-500/10 rounded-full"
          aria-hidden="true"
        />
        <div
          className="absolute -bottom-20 -right-20 w-64 h-64 bg-brand-500/5 rounded-full"
          aria-hidden="true"
        />
        <div
          className="absolute top-0 right-1/2 translate-x-1/2 w-20 h-0.5 bg-brand-500"
          aria-hidden="true"
        />

        <div className="relative p-4 sm:p-5 md:p-6">
          <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 sm:gap-4 mb-4">
            <div className="flex items-center gap-3 sm:gap-4 min-w-0">
              <div
                className="w-12 h-12 sm:w-14 sm:h-14 rounded-3xl bg-brand-gradient flex items-center justify-center text-2xl sm:text-3xl flex-shrink-0 shadow-brand"
                aria-hidden="true"
              >
                🔔
              </div>
              <div className="min-w-0">
                <h1 className="font-display font-black text-lg sm:text-xl md:text-2xl tracking-tightest leading-tight flex items-center gap-2 flex-wrap">
                  <span>اعلان‌های سیستم</span>
                  {unreadCount > 0 && (
                    <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black bg-rose-500/30 backdrop-blur border border-rose-400/40 flex-shrink-0">
                      <span
                        className="w-1.5 h-1.5 rounded-full bg-rose-300 animate-pulse"
                        aria-hidden="true"
                      />
                      <span className="font-num">{toFaRaw(unreadCount)}</span>
                      <span>جدید</span>
                    </span>
                  )}
                </h1>
                <p className="text-[11px] sm:text-xs text-cream-300/80 mt-1">
                  همهٔ رویدادهای اخیر سیستم
                </p>
              </div>
            </div>

            <div className="flex items-center gap-2 flex-wrap w-full sm:w-auto">
              {unreadCount > 0 && (
                <button
                  type="button"
                  onClick={handleMarkAllSeen}
                  className="flex-1 sm:flex-none min-h-[44px] bg-white/10 hover:bg-white/15 backdrop-blur border border-white/15 px-3 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-soft touch-target"
                >
                  <SiteImage imageKey="icon_check" fallback="✓" alt="" className="leading-none inline-flex" />
                  <span>همه را دیده‌ام</span>
                </button>
              )}
              <button
                type="button"
                onClick={() => fetchFeed(true)}
                disabled={refreshing}
                className="flex-1 sm:flex-none min-h-[44px] bg-white/10 hover:bg-white/15 backdrop-blur border border-white/15 px-3 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-soft touch-target disabled:opacity-50"
              >
                <SiteImage imageKey="icon_refresh" fallback="🔄" alt="" className="leading-none inline-flex" />
                <span>{refreshing ? 'در حال...' : 'بروزرسانی'}</span>
              </button>
            </div>
          </div>

          <div className="grid grid-cols-3 gap-2">
            <div className="bg-white/8 backdrop-blur rounded-2xl px-2 sm:px-3 py-2.5 text-center border border-white/10">
              <div className="text-[9px] sm:text-[10px] text-cream-300 mb-0.5 font-black truncate">
                📊 کل رویدادها
              </div>
              <div className="font-display font-black text-sm sm:text-base font-num tabular-nums">
                {toFaRaw(events.length)}
              </div>
            </div>
            <div className="bg-white/8 backdrop-blur rounded-2xl px-2 sm:px-3 py-2.5 text-center border border-white/10">
              <div className="text-[9px] sm:text-[10px] text-cream-300 mb-0.5 font-black truncate">
                🔴 جدید
              </div>
              <div className="font-display font-black text-sm sm:text-base text-rose-300 font-num tabular-nums">
                {toFaRaw(unreadCount)}
              </div>
            </div>
            <div className="bg-white/8 backdrop-blur rounded-2xl px-2 sm:px-3 py-2.5 text-center border border-white/10">
              <div className="text-[9px] sm:text-[10px] text-cream-300 mb-0.5 font-black truncate">
                🎯 نتیجه
              </div>
              <div className="font-display font-black text-sm sm:text-base font-num tabular-nums">
                {toFaRaw(filtered.length)}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Filters */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl shadow-soft overflow-hidden">
        <div className="p-3 sm:p-4 border-b border-ink-200 dark:border-dark-700 overflow-x-auto scrollbar-hide">
          <div className="flex gap-1.5 min-w-max sm:min-w-0 sm:flex-wrap">
            {FILTER_CHIPS.map((chip) => {
              const isActive = activeFilter === chip.key;
              return (
                <button
                  key={chip.key}
                  type="button"
                  onClick={() => setActiveFilter(chip.key)}
                  className={`min-h-[36px] px-3 py-1.5 rounded-xl border text-[11px] font-black transition flex items-center gap-1.5 flex-shrink-0 touch-target active:scale-[0.98] ${
                    isActive
                      ? 'bg-ink-900 dark:bg-cream-100 text-cream-50 dark:text-ink-900 border-ink-900 dark:border-cream-100 shadow-sm'
                      : 'bg-paper-50 dark:bg-ink-700/50 text-ink-700 dark:text-cream-200 border-ink-200 dark:border-dark-600 hover:bg-paper-100 dark:hover:bg-ink-700'
                  }`}
                >
                  <span aria-hidden="true">{chip.icon}</span>
                  <span>{chip.label}</span>
                </button>
              );
            })}
          </div>
        </div>

        <div className="p-3 sm:p-4">
          <div className="relative">
            <input
              type="text"
              value={searchInput}
              onChange={(e) => setSearchInput(e.target.value)}
              placeholder="🔍 جستجو در عنوان یا متن اعلان..."
              className="w-full px-4 py-2.5 pr-10 pl-11 min-h-[44px] border-2 border-ink-200 dark:border-dark-600 rounded-xl text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
            />
            <SiteImage imageKey="icon_search" fallback="🔍" alt="" className="absolute right-3 top-1/2 -translate-y-1/2 text-ink-400 dark:text-cream-500 pointer-events-none" />
            {searchInput && (
              <button
                type="button"
                onClick={() => setSearchInput('')}
                className="absolute left-1.5 top-1/2 -translate-y-1/2 w-8 h-8 flex items-center justify-center text-ink-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-500/15 rounded-lg transition touch-target"
                aria-label="پاک کردن جستجو"
              >
                ✕
              </button>
            )}
          </div>

          {hasActiveFilters && (
            <div className="mt-2.5 flex items-center justify-between gap-2 flex-wrap">
              <div className="text-[11px] text-ink-500 dark:text-cream-400">
                نمایش{' '}
                <span className="font-black text-ink-800 dark:text-cream-100 font-num">
                  {toFaRaw(filtered.length)}
                </span>{' '}
                از{' '}
                <span className="font-num">{toFaRaw(events.length)}</span>
              </div>
              <button
                type="button"
                onClick={clearFilters}
                className="min-h-[32px] px-3 py-1 bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 rounded-lg text-[11px] font-black transition touch-target"
              >
                ✕ پاک کردن
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Content */}
      {loading ? (
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <div
              key={i}
              className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl p-4 animate-pulse"
            >
              <div className="flex gap-3">
                <div className="w-10 h-10 rounded-xl bg-ink-100 dark:bg-ink-700" />
                <div className="flex-1 space-y-2">
                  <div className="h-4 w-2/3 bg-ink-100 dark:bg-ink-700 rounded" />
                  <div className="h-3 w-full bg-ink-100 dark:bg-ink-700 rounded" />
                </div>
              </div>
            </div>
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-10 sm:p-14 text-center shadow-soft">
          <div className="text-5xl mb-4 opacity-50" aria-hidden="true">
            🔔
          </div>
          <div className="font-display font-black text-ink-800 dark:text-cream-100 text-base mb-2">
            {hasActiveFilters ? 'نتیجه‌ای یافت نشد' : 'هیچ اعلانی وجود ندارد'}
          </div>
          <div className="text-xs text-ink-500 dark:text-cream-400 leading-relaxed max-w-sm mx-auto">
            {hasActiveFilters
              ? 'با این فیلترها هیچ رویدادی پیدا نشد. فیلترها را تغییر بده.'
              : 'وقتی رویدادی مثل سفارش جدید یا فیش واریزی ثبت بشه، اینجا نمایش داده می‌شه'}
          </div>
        </div>
      ) : (
        <div className="space-y-5">
          {groupedByDay.map((group) => (
            <div key={group.date.toISOString()}>
              <div className="flex items-center gap-3 mb-3 px-1">
                <span className="text-[11px] font-black text-ink-500 dark:text-cream-400 whitespace-nowrap">
                  {dayLabel(group.date)}
                </span>
                <div
                  className="flex-1 h-px bg-ink-200 dark:bg-dark-700"
                  aria-hidden="true"
                />
                <span className="text-[10px] bg-paper-100 dark:bg-ink-700 text-ink-600 dark:text-cream-300 px-2 py-0.5 rounded-full font-black whitespace-nowrap font-num">
                  {toFaRaw(group.events.length)}
                </span>
              </div>

              <div className="space-y-2">
                {group.events.map((ev) => {
                  const cfg = EVENT_CONFIG[ev.type] || EVENT_CONFIG.new_order;
                  const cls = COLOR_CLASSES[cfg.color] || COLOR_CLASSES.ink;
                  const unread = isUnread(ev);
                  const icon = ev.icon || cfg.icon;

                  return (
                    <div
                      key={ev.key}
                      onClick={() => handleClick(ev)}
                      role="button"
                      tabIndex={0}
                      aria-label={ev.title}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' || e.key === ' ') {
                          e.preventDefault();
                          handleClick(ev);
                        }
                      }}
                      className={`group relative bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-2xl shadow-soft hover:shadow-lifted hover:-translate-y-0.5 transition-all cursor-pointer overflow-hidden touch-target focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 focus-visible:ring-offset-paper-50 dark:focus-visible:ring-offset-ink-900 ${
                        unread
                          ? 'ring-2 ring-brand-200 dark:ring-brand-500/30'
                          : ''
                      }`}
                    >
                      <div
                        className={`absolute right-0 top-0 bottom-0 w-1 ${
                          cls.strip
                        } ${unread ? '' : 'opacity-40'}`}
                        aria-hidden="true"
                      />

                      <div className="p-3.5 sm:p-4 pr-5 flex items-start gap-3">
                        <div
                          className={`w-10 h-10 rounded-xl flex items-center justify-center text-lg flex-shrink-0 border ${cls.border} ${cls.iconBg}`}
                          aria-hidden="true"
                        >
                          {icon}
                        </div>

                        <div className="flex-1 min-w-0">
                          <div className="flex items-start gap-2 mb-1 flex-wrap">
                            <span
                              className={`text-sm font-black leading-tight flex-1 min-w-0 break-safe ${
                                unread
                                  ? 'text-ink-900 dark:text-cream-100'
                                  : 'text-ink-700 dark:text-cream-300'
                              }`}
                            >
                              {ev.title}
                            </span>
                            <span
                              className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-black border whitespace-nowrap flex-shrink-0 ${cls.chip}`}
                            >
                              {cfg.label}
                            </span>
                            {unread && (
                              <span
                                className={`w-2 h-2 rounded-full flex-shrink-0 mt-1 ${cls.strip} animate-pulse`}
                                aria-label="جدید"
                              />
                            )}
                          </div>

                          {ev.message && (
                            <div
                              className={`text-xs leading-relaxed line-clamp-2 mb-1.5 ${
                                unread
                                  ? 'text-ink-700 dark:text-cream-200'
                                  : 'text-ink-500 dark:text-cream-400'
                              }`}
                            >
                              {ev.message}
                            </div>
                          )}

                          <div className="flex items-center gap-2 text-[10px] text-ink-400 dark:text-cream-500 flex-wrap">
                            <span className="font-num">
                              {toFaTimeAgo(ev.created_at)}
                            </span>
                            {ev.priority === 'high' && (
                              <>
                                <span aria-hidden="true">·</span>
                                <span className="text-rose-600 dark:text-rose-400 font-black">
                                  فوری
                                </span>
                              </>
                            )}
                          </div>
                        </div>

                        <SiteImage imageKey="icon_arrow_left" fallback="←" alt="" className="hidden sm:inline text-ink-300 dark:text-dark-600 group-hover:text-brand-500 group-hover:-translate-x-1 transition flex-shrink-0 self-center" />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}