// frontend/src/admin/components/EmptyState.jsx
import React from 'react';

// ============================================================
//  EmptyState — نمایش حالت خالی با دکمه‌های CTA
//  🎨 Editorial: کارت کاغذی + آیکون badge + overline بالا
//
//  Props:
//    - icon: ایموجی یا المان (پیش‌فرض '📭')
//    - title: عنوان اصلی
//    - description: توضیح کوتاه
//    - actions: آرایه‌ای از { label, onClick, variant, icon }
//      variant: 'primary' | 'secondary' | 'ghost' | 'danger'
//    - size: 'sm' | 'md' | 'lg' (پیش‌فرض 'md')
//    - className: کلاس‌های اضافی
// ============================================================

// ✅ MOBILE-FIRST: padding و سایزها رسپانسیو شدن
// 🎨 Editorial: آیکون‌ها در badge دایره‌ای + radius 3xl
const SIZE_CONFIG = {
  sm: {
    wrapper: 'p-6 sm:p-8',
    iconBox: 'w-14 h-14 text-2xl mb-4',
    title: 'text-sm',
    desc: 'text-xs mt-1',
    gap: 'mt-5',
    btn: 'px-4 py-2 text-xs min-h-[40px]',
    btnFull: 'w-full sm:w-auto',
  },
  md: {
    wrapper: 'p-8 sm:p-12',
    iconBox: 'w-20 h-20 text-4xl mb-5',
    title: 'text-base',
    desc: 'text-xs mt-1.5',
    gap: 'mt-6',
    btn: 'px-4 py-2.5 text-sm min-h-[44px]',
    btnFull: 'w-full sm:w-auto',
  },
  lg: {
    wrapper: 'p-10 sm:p-16',
    iconBox: 'w-24 h-24 text-5xl mb-6',
    title: 'text-lg sm:text-xl',
    desc: 'text-xs sm:text-sm mt-2',
    gap: 'mt-7',
    btn: 'px-5 py-3 text-sm min-h-[48px]',
    btnFull: 'w-full sm:w-auto',
  },
};

// ============================================================
//  🎨 دکمه‌های EmptyState — Editorial palette
//  ✅ MOBILE: touch target + full-width در موبایل
// ============================================================
const BUTTON_VARIANTS = {
  primary:
    'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand hover:shadow-brand-lg',
  secondary:
    'bg-paper-100 dark:bg-ink-700 hover:bg-paper-200 dark:hover:bg-ink-600 active:bg-paper-300 text-ink-800 dark:text-cream-100 border border-ink-200 dark:border-dark-600',
  ghost:
    'bg-transparent hover:bg-paper-200 dark:hover:bg-ink-800 active:bg-paper-300 text-ink-700 dark:text-cream-200',
  danger:
    'bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white shadow-soft hover:shadow-lifted',
};

function EmptyAction({ label, onClick, variant = 'primary', icon, size = 'md' }) {
  const cfg = SIZE_CONFIG[size] || SIZE_CONFIG.md;
  const variantClass = BUTTON_VARIANTS[variant] || BUTTON_VARIANTS.primary;

  return (
    <button
      type="button"
      onClick={onClick}
      className={`${cfg.btn} ${cfg.btnFull} ${variantClass} rounded-2xl font-black transition-all duration-300 flex items-center justify-center gap-2 touch-target hover:-translate-y-0.5 active:translate-y-0 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand-500 focus-visible:ring-offset-2 focus-visible:ring-offset-paper-50 dark:focus-visible:ring-offset-ink-900`}
    >
      {icon && (
        <span className="text-base flex-shrink-0" aria-hidden="true">
          {icon}
        </span>
      )}
      <span>{label}</span>
    </button>
  );
}

// ============================================================
//  کامپوننت اصلی
//  🎨 Editorial: overline بالا + آیکون در badge + noise overlay
//  ♿ role="status" + aria-live="polite" — برای اعلام تغییر state
// ============================================================
export default function EmptyState({
  icon = '📭',
  title,
  description,
  actions = [],
  size = 'md',
  className = '',
}) {
  const cfg = SIZE_CONFIG[size] || SIZE_CONFIG.md;

  return (
    <div
      role="status"
      aria-live="polite"
      className={`relative bg-paper-50 dark:bg-ink-800/60 rounded-3xl border border-ink-200 dark:border-dark-700 shadow-soft text-center overflow-hidden noise-overlay ${cfg.wrapper} ${className}`}
      dir="rtl"
    >
      {/* Overline تزئینی بالا */}
      <div
        className="absolute top-0 right-1/2 translate-x-1/2 w-16 h-0.5 bg-brand-500"
        aria-hidden="true"
      />

      {/* آیکون در badge دایره‌ای */}
      <div
        className={`mx-auto rounded-3xl bg-paper-100 dark:bg-ink-900 flex items-center justify-center shadow-soft ${cfg.iconBox}`}
        aria-hidden="true"
      >
        <span className="leading-none select-none">{icon}</span>
      </div>

      {/* عنوان */}
      {title && (
        <div
          className={`font-display font-black text-ink-900 dark:text-cream-100 tracking-tight ${cfg.title}`}
        >
          {title}
        </div>
      )}

      {/* توضیحات */}
      {description && (
        <div
          className={`text-ink-500 dark:text-cream-400 ${cfg.desc} max-w-md mx-auto leading-relaxed px-2 break-safe`}
        >
          {description}
        </div>
      )}

      {/* دکمه‌ها — روی موبایل تمام عرض، روی دسکتاپ کنار هم */}
      {actions.length > 0 && (
        <div
          className={`flex flex-col sm:flex-row flex-wrap items-stretch sm:items-center justify-center gap-2.5 ${cfg.gap} max-w-xs sm:max-w-none mx-auto`}
        >
          {actions.map((action) => (
            <EmptyAction
              key={action.label || action.variant}
              {...action}
              size={size}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
//  EmptyState های آماده برای کاربردهای رایج
//  (می‌تونی مستقیم import کنی بدون props دادن)
// ============================================================

/** هیچ نتیجه‌ای از جستجو/فیلتر پیدا نشد */
export function EmptySearch({
  searchTerm,
  onClear,
  size = 'md',
  className = '',
}) {
  return (
    <EmptyState
      icon="🔍"
      title="نتیجه‌ای یافت نشد"
      description={
        searchTerm
          ? `عبارت «${searchTerm}» در هیچ موردی پیدا نشد. می‌تونی عبارت دیگه‌ای امتحان کنی یا فیلترها رو پاک کنی.`
          : 'با این فیلترها نتیجه‌ای پیدا نشد. می‌تونی فیلترها رو تغییر بدی.'
      }
      actions={
        onClear
          ? [
              {
                label: 'پاک کردن فیلترها',
                onClick: onClear,
                variant: 'secondary',
                icon: '✕', iconKey: 'icon_close',
              },
            ]
          : []
      }
      size={size}
      className={className}
    />
  );
}

/** هیچ سفارشی ثبت نشده */
export function EmptyOrders({
  onGoToOrders,
  onGoToNewOrder,
  size = 'md',
  className = '',
}) {
  const actions = [];
  if (onGoToNewOrder) {
    actions.push({
      label: 'ثبت سفارش جدید',
      onClick: onGoToNewOrder,
      variant: 'primary',
      icon: '➕', iconKey: 'icon_plus',
    });
  }
  if (onGoToOrders) {
    actions.push({
      label: 'مشاهده سفارشات',
      onClick: onGoToOrders,
      variant: 'secondary',
      icon: '📋', iconKey: 'icon_clipboard',
    });
  }

  return (
    <EmptyState
      icon="📦"
      title="هنوز سفارشی ثبت نشده"
      description="وقتی اولین سفارش از طرف کاربرا ثبت بشه، اینجا نمایش داده می‌شه."
      actions={actions}
      size={size}
      className={className}
    />
  );
}

/** هیچ کاربری ثبت‌نام نکرده */
export function EmptyUsers({ size = 'md', className = '' }) {
  return (
    <EmptyState
      icon="👥"
      title="هنوز کاربری ثبت‌نام نکرده"
      description="کاربران با مراجعه به صفحه اصلی و ثبت‌نام، به این لیست اضافه می‌شن."
      size={size}
      className={className}
    />
  );
}

/** هیچ تیکتی نیست */
export function EmptyTickets({
  hasFilters,
  onClear,
  size = 'md',
  className = '',
}) {
  // ✅ FIX: پیام متناسب با وجود یا نبود دکمهٔ پاک کردن
  const canClear = Boolean(hasFilters && onClear);
  return (
    <EmptyState
      icon="🎫"
      title={
        hasFilters
          ? 'تیکتی با این فیلترها یافت نشد'
          : 'هیچ تیکتی وجود ندارد'
      }
      description={
        hasFilters
          ? canClear
            ? 'می‌تونی فیلترها رو پاک کنی یا عبارت جستجو رو تغییر بدی.'
            : 'هیچ تیکتی با این فیلترها مطابقت ندارد.'
          : 'وقتی کاربران تیکت بزنن، اینجا نمایش داده می‌شن.'
      }
      actions={
        canClear
          ? [
              {
                label: 'پاک کردن فیلترها',
                onClick: onClear,
                variant: 'secondary',
                icon: '✕', iconKey: 'icon_close',
              },
            ]
          : []
      }
      size={size}
      className={className}
    />
  );
}

/** داده‌ای برای نمودار/گزارش نیست */
export function EmptyChart({
  title = 'داده‌ای برای نمایش نیست',
  description = 'در بازه انتخابی هیچ سفارشی ثبت نشده است.',
  actions = [],
  size = 'md',
  className = '',
}) {
  return (
    <EmptyState
      icon="📊"
      title={title}
      description={description}
      actions={actions}
      size={size}
      className={className}
    />
  );
}

