// frontend/src/admin/components/DeliveryCitiesManager.jsx
// ============================================================
//  ✅ RESPONSIVE FIX:
//  - این فایل از قبل ریسپانسیو بود (flex-col sm:flex-row، w-full sm:w-auto،
//    flex-wrap، text-[10px] sm:text-[11px])
//  - تنها بهبود: ارتفاع نقشه در موبایل کوچیک‌تر (220px) تا scroll کمتر بشه
//  - در دسکتاپ ارتفاع 320px حفظ شده
//  ✅ FIX (v2): پشتیبانی از کیبورد فارسی و ممیز در فیلد شعاع پوشش
//  ✅ FIX (API): حذف API_BASE محلی → مسیرهای نسبی با axiosConfig
// ============================================================
import React, { useState, useEffect, useCallback, useRef } from 'react';
import axios from '../axiosConfig';
import { toFa, toFaDecimal } from '../../utils/numbers';
import {
  MapContainer,
  TileLayer,
  Marker,
  Circle,
  useMapEvents,
  useMap,
} from 'react-leaflet';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { SiteImage } from '../../utils/SiteImage';

// ✅ FIX: نرمال‌سازی اعداد فارسی/عربی و ممیز فارسی برای ورودی‌های عددی
const normalizeDigits = (value) =>
  String(value ?? '')
    .replace(/[۰-۹]/g, (d) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)))
    .replace(/[٠-٩]/g, (d) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/٫/g, '.');

// ============================================================
//  Fix Leaflet Default Marker Icon (issue شناخته‌شده در CRA)
// ============================================================
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
});

// ============================================================
//  ثابت‌ها
// ============================================================
const TEHRAN_CENTER = [35.6892, 51.389];
const DEFAULT_RADIUS = 10;
const MIN_RADIUS = 1;
const MAX_RADIUS = 150;

// ✅ FIX: breakpoint برای ارتفاع پویای نقشه
// زیر 640px (موبایل) = ارتفاع کمتر، بالای 640px = ارتفاع کامل
const MAP_MOBILE_BREAKPOINT = 640;

// ============================================================
//  کامپوننت‌های کمکی نقشه
// ============================================================
function MapClickHandler({ onMapClick }) {
  useMapEvents({
    click(e) {
      onMapClick(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
}

function MapRecenter({ center, zoom }) {
  const map = useMap();
  useEffect(() => {
    if (center && center[0] && center[1]) {
      const targetZoom = zoom ?? Math.max(map.getZoom(), 10);
      map.setView(center, targetZoom, { animate: true });
    }
  }, [center, zoom, map]);
  return null;
}

function MapResizer() {
  const map = useMap();
  useEffect(() => {
    const t = setTimeout(() => map.invalidateSize(), 200);
    return () => clearTimeout(t);
  }, [map]);
  return null;
}

// ============================================================
//  کامپوننت اصلی
// ============================================================
export default function DeliveryCitiesManager({ showToast }) {
  const [cities, setCities] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  const [formOpen, setFormOpen] = useState(false);
  const [editingIndex, setEditingIndex] = useState(null);
  const [form, setForm] = useState({
    name: '',
    lat: '',
    lng: '',
    radius_km: String(DEFAULT_RADIUS),
    active: true,
  });
  const [formError, setFormError] = useState('');

  const [searching, setSearching] = useState(false);
  const [mapCenter, setMapCenter] = useState(TEHRAN_CENTER);
  const [deletingIndex, setDeletingIndex] = useState(null);

  // ✅ FIX: isMobile state برای ارتفاع پویای نقشه
  const [isMobile, setIsMobile] = useState(() =>
    typeof window !== 'undefined' ? window.innerWidth < MAP_MOBILE_BREAKPOINT : false
  );

  const isMountedRef = useRef(true);
  const searchAbortRef = useRef(null);

  // ✅ FIX: useEffect برای tracking resize
  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < MAP_MOBILE_BREAKPOINT);
    check();
    window.addEventListener('resize', check);
    return () => window.removeEventListener('resize', check);
  }, []);

  // ============================================================
  //  Cleanup on unmount
  // ============================================================
  useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
      if (searchAbortRef.current) {
        try {
          searchAbortRef.current.abort();
        } catch {
          /* silent */
        }
      }
    };
  }, []);

  // ============================================================
  //  Load
  // ============================================================
  const fetchCities = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get('/admin/settings');
      if (!isMountedRef.current) return;

      const raw = res.data?.delivery_cities;
      if (raw) {
        try {
          const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
          if (Array.isArray(parsed)) {
            setCities(parsed);
          } else {
            setCities([]);
          }
        } catch {
          setCities([]);
        }
      } else {
        setCities([]);
      }
    } catch {
      if (!isMountedRef.current) return;
      showToast?.('error', 'خطا در دریافت لیست شهرها');
    } finally {
      if (isMountedRef.current) setLoading(false);
    }
  }, [showToast]);

  useEffect(() => {
    fetchCities();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // ============================================================
  //  Save
  // ============================================================
  const saveCities = useCallback(
    async (newCities) => {
      setSaving(true);
      try {
        await axios.put('/admin/settings', {
          delivery_cities: JSON.stringify(newCities),
        });
        if (!isMountedRef.current) return false;
        setCities(newCities);
        showToast?.('success', 'لیست شهرها ذخیره شد');
        return true;
      } catch {
        if (!isMountedRef.current) return false;
        showToast?.('error', 'خطا در ذخیره لیست شهرها');
        return false;
      } finally {
        if (isMountedRef.current) setSaving(false);
      }
    },
    [showToast]
  );

  const openAddForm = () => {
    setEditingIndex(null);
    setForm({
      name: '',
      lat: '',
      lng: '',
      radius_km: String(DEFAULT_RADIUS),
      active: true,
    });
    setFormError('');
    setMapCenter(TEHRAN_CENTER);
    setFormOpen(true);
  };

  const openEditForm = (index) => {
    const city = cities[index];
    setEditingIndex(index);
    setForm({
      name: city.name || '',
      lat: String(city.lat ?? ''),
      lng: String(city.lng ?? ''),
      // ✅ FIX: مقدار اولیه به رشته برای سازگاری با type="text"
      radius_km: String(
        Number(city.radius_km) > 0 ? Number(city.radius_km) : DEFAULT_RADIUS
      ),
      active: city.active !== false,
    });
    setFormError('');
    if (city.lat && city.lng) {
      setMapCenter([Number(city.lat), Number(city.lng)]);
    }
    setFormOpen(true);
  };

  const closeForm = () => {
    // اگر جستجو در جریان است، لغو کن
    if (searchAbortRef.current) {
      try {
        searchAbortRef.current.abort();
      } catch {
        /* silent */
      }
      searchAbortRef.current = null;
    }
    setFormOpen(false);
    setEditingIndex(null);
    setFormError('');
    setSearching(false);
  };

  // ============================================================
  //  جستجوی شهر با Nominatim
  // ============================================================
  const handleSearch = async () => {
    const q = form.name.trim();
    if (!q) {
      setFormError('نام شهر را وارد کنید');
      return;
    }

    // لغو جستجوی قبلی در صورت وجود
    if (searchAbortRef.current) {
      try {
        searchAbortRef.current.abort();
      } catch {
        /* silent */
      }
    }
    const controller = new AbortController();
    searchAbortRef.current = controller;

    setSearching(true);
    setFormError('');
    try {
      const url =
        `https://nominatim.openstreetmap.org/search` +
        `?format=json&q=${encodeURIComponent(q)}` +
        `&countrycodes=ir&accept-language=fa&limit=1`;

      const res = await fetch(url, {
        headers: { Accept: 'application/json' },
        signal: controller.signal,
      });
      const data = await res.json();

      if (!isMountedRef.current) return;

      if (!Array.isArray(data) || data.length === 0) {
        setFormError(
          'شهری با این نام پیدا نشد. می‌توانید روی نقشه کلیک کنید.'
        );
        return;
      }

      const found = data[0];
      const lat = Number(found.lat);
      const lng = Number(found.lon);

      setForm((prev) => ({
        ...prev,
        lat: String(lat),
        lng: String(lng),
        name: prev.name.trim() || q,
      }));
      setMapCenter([lat, lng]);
    } catch (err) {
      if (err?.name === 'AbortError') return; // لغو عمدی
      if (!isMountedRef.current) return;
      setFormError('خطا در جستجو. اتصال اینترنت را بررسی کنید.');
    } finally {
      if (isMountedRef.current) setSearching(false);
      searchAbortRef.current = null;
    }
  };

  const handleSearchKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSearch();
    }
  };

  const handleMapClick = (lat, lng) => {
    // ✅ FIX: جلوگیری از تغییر نقشه حین ذخیره
    if (saving) return;
    setForm((prev) => ({
      ...prev,
      lat: String(lat.toFixed(6)),
      lng: String(lng.toFixed(6)),
    }));
    setMapCenter([lat, lng]);
    setFormError('');
  };

  const handleFormChange = (e) => {
    const { name, value, type, checked } = e.target;

    let nextValue = type === 'checkbox' ? checked : value;

    // ✅ FIX: نرمال‌سازی اعداد فارسی/عربی و ممیز برای فیلد شعاع
    if (name === 'radius_km') {
      nextValue = normalizeDigits(nextValue);
    }

    setForm((prev) => ({
      ...prev,
      [name]: nextValue,
    }));
    setFormError('');
  };

  // ============================================================
  //  ذخیره فرم
  // ============================================================
  const handleSaveForm = async () => {
    const name = form.name.trim();
    const lat = parseFloat(form.lat);
    const lng = parseFloat(form.lng);
    const radius = parseFloat(normalizeDigits(form.radius_km));

    if (!name) {
      setFormError('نام شهر الزامی است');
      return;
    }
    if (isNaN(lat) || lat < -90 || lat > 90) {
      setFormError(
        'عرض جغرافیایی نامعتبر است. روی نقشه کلیک کنید یا جستجو کنید.'
      );
      return;
    }
    if (isNaN(lng) || lng < -180 || lng > 180) {
      setFormError(
        'طول جغرافیایی نامعتبر است. روی نقشه کلیک کنید یا جستجو کنید.'
      );
      return;
    }
    if (isNaN(radius) || radius < MIN_RADIUS || radius > MAX_RADIUS) {
      // ✅ FIX: ارقام فارسی در پیام خطا
      setFormError(
        `شعاع باید بین ${toFa(MIN_RADIUS)} و ${toFa(MAX_RADIUS)} کیلومتر باشد`
      );
      return;
    }

    const dupIndex = cities.findIndex(
      (c, i) => i !== editingIndex && (c.name || '').trim() === name
    );
    if (dupIndex !== -1) {
      setFormError('شهری با این نام قبلاً اضافه شده است');
      return;
    }

    const newCity = {
      name,
      lat,
      lng,
      radius_km: radius,
      active: !!form.active,
    };

    let nextCities;
    if (editingIndex === null) {
      nextCities = [...cities, newCity];
    } else {
      nextCities = cities.map((c, i) => (i === editingIndex ? newCity : c));
    }

    const ok = await saveCities(nextCities);
    if (ok) {
      closeForm();
    }
  };

  const handleDelete = async (index) => {
    const nextCities = cities.filter((_, i) => i !== index);
    const ok = await saveCities(nextCities);
    if (ok) setDeletingIndex(null);
  };

  const handleToggleActive = async (index) => {
    const nextCities = cities.map((c, i) =>
      i === index ? { ...c, active: !(c.active !== false) } : c
    );
    await saveCities(nextCities);
  };

  // ============================================================
  //  Loading — فقط در mount اولیه
  // ============================================================
  if (loading && cities.length === 0) {
    return (
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl p-6 text-center shadow-soft">
        <div className="inline-block w-8 h-8 border-4 border-brand-500 border-t-transparent rounded-full animate-spin mb-2" />
        <div className="text-sm text-ink-500 dark:text-cream-400 font-bold">
          در حال بارگذاری شهرها...
        </div>
      </div>
    );
  }

  const formLat = parseFloat(form.lat);
  const formLng = parseFloat(form.lng);
  const formRadius = parseFloat(normalizeDigits(form.radius_km)) || DEFAULT_RADIUS;
  const hasPosition = !isNaN(formLat) && !isNaN(formLng);
  const canSearch = !!form.name.trim() && !saving && !searching;

  return (
    <div className="space-y-3 sm:space-y-4">
      {/* ============================================================ */}
      {/*  Header + Add Button                                         */}
      {/* ============================================================ */}
      <div className="bg-paper-50 dark:bg-ink-800 border border-ink-200 dark:border-dark-700 rounded-3xl shadow-soft overflow-hidden">
        <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3 bg-brand-50/50 dark:bg-brand-500/10">
          <div className="flex items-center gap-3 min-w-0">
            <div
              className="w-10 h-10 sm:w-11 sm:h-11 rounded-2xl bg-brand-gradient flex items-center justify-center text-lg sm:text-xl flex-shrink-0 shadow-brand text-white"
              aria-hidden="true"
            >
              🗺️
            </div>
            <div className="min-w-0">
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                شهرهای مجاز تحویل
              </div>
              <div className="text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 leading-relaxed font-bold">
                مشتری فقط داخل محدوده این شهرها می‌تواند سفارش بدهد
              </div>
            </div>
          </div>

          {!formOpen && (
            <button
              type="button"
              onClick={openAddForm}
              disabled={saving}
              className="w-full sm:w-auto min-h-[44px] px-4 py-2.5 bg-brand-gradient hover:opacity-95 active:opacity-90 text-white rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 shadow-brand hover:shadow-brand-lg touch-target flex-shrink-0 disabled:opacity-50"
            >
              <SiteImage imageKey="icon_plus" fallback="➕" alt="" className="text-base" />
              <span>افزودن شهر جدید</span>
            </button>
          )}
        </div>

        <div className="p-3 sm:p-4">
          {cities.length === 0 ? (
            <div className="text-center py-8 sm:py-10 border-2 border-dashed border-ink-200 dark:border-dark-600 rounded-2xl bg-paper-100/50 dark:bg-ink-900/30">
              <div
                className="text-4xl sm:text-5xl mb-3 opacity-60"
                aria-hidden="true"
              >
                🏙️
              </div>
              <div className="text-sm font-display font-black text-ink-700 dark:text-cream-200 mb-1">
                هنوز شهری اضافه نشده
              </div>
              <div className="text-[11px] text-ink-500 dark:text-cream-400 mb-4 px-4 leading-relaxed font-bold">
                برای شروع، اولین شهر مجاز تحویل را اضافه کنید
              </div>
              {!formOpen && (
                <button
                  type="button"
                  onClick={openAddForm}
                  className="inline-flex items-center gap-2 min-h-[44px] bg-brand-gradient hover:opacity-95 active:opacity-90 text-white px-4 py-2.5 rounded-2xl text-xs font-black transition shadow-brand touch-target"
                >
                  <SiteImage imageKey="icon_plus" fallback="➕" alt="" className="leading-none inline-flex" />
                  <span>افزودن اولین شهر</span>
                </button>
              )}
            </div>
          ) : (
            <div className="space-y-2">
              {cities.map((city, index) => {
                const isActive = city.active !== false;
                const isDeleting = deletingIndex === index;
                return (
                  <div
                    key={`${city.name}-${index}`}
                    className={`rounded-2xl border-2 overflow-hidden transition ${
                      isActive
                        ? 'bg-paper-50 dark:bg-ink-800 border-ink-200 dark:border-dark-600'
                        : 'bg-paper-100 dark:bg-ink-700/40 border-ink-200 dark:border-dark-700 opacity-70'
                    }`}
                  >
                    <div className="p-3 flex items-center gap-2.5 min-w-0">
                      <div
                        className={`w-10 h-10 rounded-2xl flex items-center justify-center text-lg flex-shrink-0 ${
                          isActive
                            ? 'bg-brand-50 dark:bg-brand-500/15 text-brand-700 dark:text-brand-300'
                            : 'bg-ink-100 dark:bg-ink-700 text-ink-500 dark:text-cream-400'
                        }`}
                      >
                        🏙️
                      </div>

                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-display font-black text-ink-800 dark:text-cream-100 text-sm truncate">
                            {city.name}
                          </span>
                          {isActive ? (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black bg-accent-50 dark:bg-accent-500/15 text-accent-700 dark:text-accent-300 border border-accent-200 dark:border-accent-500/30 flex-shrink-0">
                              <span
                                className="w-1.5 h-1.5 rounded-full bg-accent-500"
                                aria-hidden="true"
                              />
                              فعال
                            </span>
                          ) : (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-black bg-ink-100 dark:bg-ink-700 text-ink-500 dark:text-cream-400 border border-ink-200 dark:border-dark-600 flex-shrink-0">
                              <span
                                className="w-1.5 h-1.5 rounded-full bg-ink-400"
                                aria-hidden="true"
                              />
                              غیرفعال
                            </span>
                          )}
                        </div>
                        <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-0.5 flex items-center gap-2 flex-wrap font-bold">
                          <span>
                            📏 شعاع:{' '}
                            <span className="font-num font-black tabular-nums">
                              {Number(city.radius_km || 0).toLocaleString(
                                'fa-IR'
                              )}{' '}
                              km
                            </span>
                          </span>
                          <span
                            className="text-ink-300 dark:text-dark-600"
                            aria-hidden="true"
                          >
                            ·
                          </span>
                          {/* ✅ FIX: ارقام فارسی */}
                          <span
                            className="font-num tabular-nums"
                            dir="ltr"
                          >
                            📍 {toFaDecimal(city.lat, 3)},{' '}
                            {toFaDecimal(city.lng, 3)}
                          </span>
                        </div>
                      </div>

                      <div className="flex items-center gap-1 flex-shrink-0">
                        <button
                          type="button"
                          onClick={() => handleToggleActive(index)}
                          disabled={saving}
                          className={`w-9 h-9 min-h-[36px] flex items-center justify-center rounded-2xl transition text-sm touch-target disabled:opacity-50 ${
                            isActive
                              ? 'bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 text-brand-600 dark:text-brand-400'
                              : 'bg-accent-50 dark:bg-accent-500/15 hover:bg-accent-100 dark:hover:bg-accent-500/25 text-accent-600 dark:text-accent-400'
                          }`}
                          title={isActive ? 'غیرفعال کردن' : 'فعال کردن'}
                        >
                          {isActive ? '🚫' : '✅'}
                        </button>

                        <button
                          type="button"
                          onClick={() => openEditForm(index)}
                          disabled={saving || formOpen}
                          className="w-9 h-9 min-h-[36px] flex items-center justify-center rounded-2xl bg-brand-50 dark:bg-brand-500/15 hover:bg-brand-100 dark:hover:bg-brand-500/25 text-brand-600 dark:text-brand-400 transition text-sm touch-target disabled:opacity-50"
                          title="ویرایش"
                        >
                          ✏️
                        </button>

                        <button
                          type="button"
                          onClick={() =>
                            setDeletingIndex(isDeleting ? null : index)
                          }
                          disabled={saving}
                          className="w-9 h-9 min-h-[36px] flex items-center justify-center rounded-2xl bg-rose-50 dark:bg-rose-500/15 hover:bg-rose-100 dark:hover:bg-rose-500/25 text-rose-600 dark:text-rose-400 transition text-sm touch-target disabled:opacity-50"
                          title="حذف"
                        >
                          🗑️
                        </button>
                      </div>
                    </div>

                    {isDeleting && (
                      <div className="px-3 pb-3 border-t border-rose-200 dark:border-rose-500/30 bg-rose-50/60 dark:bg-rose-500/10 animate-expand-down">
                        <div className="pt-3 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
                          <span className="text-xs text-rose-700 dark:text-rose-300 font-black">
                            شهر «{city.name}» حذف شود؟
                          </span>
                          <div className="flex gap-2">
                            <button
                              type="button"
                              onClick={() => setDeletingIndex(null)}
                              disabled={saving}
                              className="flex-1 sm:flex-none min-h-[36px] px-3 py-1.5 bg-paper-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 rounded-2xl text-xs font-black touch-target disabled:opacity-50"
                            >
                              انصراف
                            </button>
                            <button
                              type="button"
                              onClick={() => handleDelete(index)}
                              disabled={saving}
                              className="flex-1 sm:flex-none min-h-[36px] px-3 py-1.5 bg-rose-500 hover:bg-rose-600 active:bg-rose-700 text-white rounded-2xl text-xs font-black touch-target disabled:opacity-50"
                            >
                              {saving ? 'در حال حذف...' : 'حذف'}
                            </button>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* ============================================================ */}
      {/*  Form (افزودن/ویرایش)                                        */}
      {/* ============================================================ */}
      {formOpen && (
        <div className="bg-paper-50 dark:bg-ink-800 border-2 border-brand-300 dark:border-brand-500/40 rounded-3xl shadow-editorial overflow-hidden animate-expand-down">
          <div className="px-4 sm:px-5 py-3 sm:py-4 border-b border-ink-200 dark:border-dark-700 flex items-center gap-3 bg-brand-50/50 dark:bg-brand-500/10">
            <div
              className="w-10 h-10 rounded-2xl bg-brand-gradient flex items-center justify-center text-lg flex-shrink-0 shadow-brand text-white"
              aria-hidden="true"
            >
              {editingIndex === null ? '➕' : '✏️'}
            </div>
            <div className="flex-1 min-w-0">
              <div className="font-display font-black text-ink-800 dark:text-cream-100 text-sm">
                {editingIndex === null ? 'افزودن شهر جدید' : 'ویرایش شهر'}
              </div>
              <div className="text-[10px] sm:text-[11px] text-ink-500 dark:text-cream-400 mt-0.5 leading-relaxed font-bold">
                نام شهر را تایپ کنید یا روی نقشه کلیک کنید
              </div>
            </div>
            <button
              type="button"
              onClick={closeForm}
              disabled={saving}
              className="w-10 h-10 flex items-center justify-center text-ink-400 hover:text-rose-600 hover:bg-rose-50 dark:hover:bg-rose-500/15 active:bg-rose-100 rounded-2xl transition flex-shrink-0 touch-target disabled:opacity-50"
              title="بستن"
              aria-label="بستن"
            >
              ✕
            </button>
          </div>

          <div className="p-3 sm:p-5 space-y-4">
            <div>
              <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200 mb-1.5">
                <span aria-hidden="true">🏙️</span>
                <span>نام شهر</span>
                <span className="text-brand-500">*</span>
              </label>
              <div className="flex flex-col sm:flex-row gap-2">
                <input
                  type="text"
                  name="name"
                  value={form.name}
                  onChange={handleFormChange}
                  onKeyDown={handleSearchKeyDown}
                  placeholder="مثال: تهران"
                  className="flex-1 min-w-0 px-3 py-2.5 min-h-[48px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-base sm:text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 placeholder-ink-400 dark:placeholder-cream-500 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition"
                  disabled={saving}
                />
                <button
                  type="button"
                  onClick={handleSearch}
                  disabled={!canSearch}
                  className={`w-full sm:w-auto min-h-[48px] px-4 py-2.5 rounded-2xl text-xs font-black transition flex items-center justify-center gap-2 touch-target ${
                    canSearch
                      ? 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white shadow-brand'
                      : 'bg-paper-200 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                  }`}
                  title="جستجوی مختصات شهر"
                >
                  {searching ? (
                    <>
                      <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                      <span>در حال جستجو...</span>
                    </>
                  ) : (
                    <>
                      <SiteImage imageKey="icon_search" fallback="🔍" alt="" className="leading-none inline-flex" />
                      <span>جستجو روی نقشه</span>
                    </>
                  )}
                </button>
              </div>

              <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed font-bold">
                💡 نام شهر را در بالا وارد و روی «جستجو روی نقشه» بزنید (یا
                Enter بزنید) تا مختصات خودکار پر شود. اگر شهر پیدا نشد،
                مستقیماً روی نقشه کلیک کنید.
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-1.5 gap-2 flex-wrap">
                <label className="flex items-center gap-1.5 text-xs font-black text-ink-800 dark:text-cream-200">
                  <span aria-hidden="true">🗺️</span>
                  <span>موقعیت مرکز شهر</span>
                </label>
                {hasPosition && (
                  // ✅ FIX: ارقام فارسی
                  <span
                    className="text-[10px] text-ink-500 dark:text-cream-400 font-num tabular-nums font-black"
                    dir="ltr"
                  >
                    {toFaDecimal(formLat, 4)}, {toFaDecimal(formLng, 4)}
                  </span>
                )}
              </div>

              <div className="text-[10px] text-ink-500 dark:text-cream-400 mb-2 flex items-center gap-1.5 leading-relaxed font-bold">
                <SiteImage imageKey="icon_hand_point" fallback="👆" alt="" className="leading-none inline-flex" />
                <span>روی نقشه کلیک کنید تا مارکر جابه‌جا شود</span>
              </div>

              <div
                className="rounded-2xl overflow-hidden border-2 border-ink-200 dark:border-dark-600"
                style={{ height: isMobile ? '220px' : '320px' }}
              >
                <MapContainer
                  center={mapCenter}
                  zoom={hasPosition ? 11 : 5}
                  scrollWheelZoom={false}
                  style={{ height: '100%', width: '100%' }}
                >
                  <TileLayer
                    attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                    url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                  />
                  <MapResizer />
                  <MapClickHandler onMapClick={handleMapClick} />
                  <MapRecenter center={mapCenter} />

                  {hasPosition && (
                    <>
                      <Marker position={[formLat, formLng]} />
                      <Circle
                        center={[formLat, formLng]}
                        radius={formRadius * 1000}
                        pathOptions={{
                          color: '#AF6B24',
                          fillColor: '#AF6B24',
                          fillOpacity: 0.15,
                          weight: 2,
                        }}
                      />
                    </>
                  )}
                </MapContainer>
              </div>
            </div>

            <div>
              <label className="flex items-center justify-between gap-2 text-xs font-black text-ink-800 dark:text-cream-200 mb-2 flex-wrap">
                <span className="flex items-center gap-1.5">
                  <SiteImage imageKey="icon_ruler" fallback="📏" alt="" className="leading-none inline-flex" />
                  <span>شعاع پوشش (کیلومتر)</span>
                </span>
                <span className="text-brand-700 dark:text-brand-300 font-num text-sm tabular-nums font-black">
                  {Number(formRadius || 0).toLocaleString('fa-IR')} km
                </span>
              </label>

              <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
                <input
                  type="range"
                  name="radius_km"
                  min={MIN_RADIUS}
                  max={MAX_RADIUS}
                  step="1"
                  value={formRadius}
                  onChange={handleFormChange}
                  disabled={saving}
                  className="flex-1 h-2 accent-brand-500 cursor-pointer touch-target"
                />
                <div className="relative w-full sm:w-32">
                  {/* ✅ FIX: type="text" + inputMode برای پشتیبانی از کیبورد فارسی و ممیز */}
                  <input
                    type="text"
                    inputMode="decimal"
                    name="radius_km"
                    value={form.radius_km}
                    onChange={handleFormChange}
                    disabled={saving}
                    className="w-full px-3 py-2.5 min-h-[44px] border-2 border-ink-200 dark:border-dark-600 rounded-2xl text-base sm:text-sm bg-paper-50 dark:bg-ink-700 text-ink-900 dark:text-cream-100 focus:ring-2 focus:ring-brand-500/30 focus:border-brand-500 outline-none transition text-center font-num tabular-nums"
                    dir="ltr"
                  />
                  <span className="absolute left-2 top-1/2 -translate-y-1/2 text-ink-400 text-[10px] font-black pointer-events-none">
                    km
                  </span>
                </div>
              </div>

              <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-1.5 leading-relaxed font-bold">
                مشتری فقط داخل این محدوده (دایره روی نقشه) می‌تواند سفارش
                بدهد
              </div>
            </div>

            <label className="flex items-center gap-2.5 p-3 rounded-2xl border-2 border-ink-200 dark:border-dark-600 bg-paper-100 dark:bg-ink-700/40 cursor-pointer min-h-[52px] hover:border-brand-300 dark:hover:border-brand-500/40 transition">
              <input
                type="checkbox"
                name="active"
                checked={form.active}
                onChange={handleFormChange}
                disabled={saving}
                className="w-5 h-5 accent-brand-500 cursor-pointer"
              />
              <div className="flex-1 min-w-0">
                <div className="text-xs font-black text-ink-700 dark:text-cream-200">
                  شهر فعال باشد
                </div>
                <div className="text-[10px] text-ink-500 dark:text-cream-400 mt-0.5 leading-relaxed font-bold">
                  اگر غیرفعال باشد، مشتری نمی‌تواند این شهر را انتخاب کند
                </div>
              </div>
            </label>

            {formError && (
              <div className="bg-rose-50 dark:bg-rose-500/15 border border-rose-200 dark:border-rose-500/30 text-rose-700 dark:text-rose-300 p-3 rounded-2xl text-xs flex items-start gap-2 animate-slide-down break-safe font-bold">
                <span className="flex-shrink-0" aria-hidden="true">
                  ⚠️
                </span>
                <span>{formError}</span>
              </div>
            )}

            <div className="flex flex-col-reverse sm:flex-row gap-2 pt-2">
              <button
                type="button"
                onClick={closeForm}
                disabled={saving}
                className="w-full sm:w-auto min-h-[48px] px-5 py-2.5 bg-paper-50 dark:bg-ink-700 border border-ink-200 dark:border-dark-600 text-ink-700 dark:text-cream-200 rounded-2xl text-sm font-black hover:bg-paper-100 dark:hover:bg-ink-600 active:bg-paper-200 transition touch-target disabled:opacity-50"
              >
                انصراف
              </button>
              <button
                type="button"
                onClick={handleSaveForm}
                disabled={saving || !hasPosition}
                className={`w-full sm:flex-1 min-h-[48px] px-6 py-2.5 rounded-2xl text-sm font-black transition flex items-center justify-center gap-2 shadow-brand touch-target ${
                  saving || !hasPosition
                    ? 'bg-paper-200 dark:bg-ink-700 text-ink-400 dark:text-cream-500 cursor-not-allowed'
                    : 'bg-brand-gradient hover:opacity-95 active:opacity-90 text-white hover:shadow-brand-lg'
                }`}
              >
                {saving ? (
                  <>
                    <span className="inline-block w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                    <span>در حال ذخیره...</span>
                  </>
                ) : (
                  <>
                    <SiteImage imageKey="icon_save" fallback="💾" alt="" className="leading-none inline-flex" />
                    <span>
                      {editingIndex === null ? 'افزودن شهر' : 'ذخیره تغییرات'}
                    </span>
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}