// ============================================================
//  Helper: تبدیل به فارسی فقط اگر مقدار عددی باشد
//  (برای temp/time که گاهی رشته‌ای مثل «سرد» یا «-» هستند)
// ============================================================
const toFaIfNumeric = (value) => {
  if (value === null || value === undefined || value === '') return '—';
  if (typeof value === 'number') return toFa(value);
  if (typeof value === 'string' && /^-?\d+$/.test(value)) return toFa(value);
  return value;
};

